:root {
  --bg: #1a1c2c;
  --card: #2a2d3e;
  --accent: #ffcd75;
  --text: #f4f4f4;
  --muted: #a0a0b0;
  --pressed: #ef7d57;
}
* { box-sizing: border-box; margin: 0; padding: 0; }
body {
  background: var(--bg);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
  color: var(--text);
}
.elevator-card {
  background: var(--card);
  border-radius: 16px;
  padding: 24px;
  width: 100%;
  max-width: 420px;
  box-shadow: 0 8px 24px rgba(0,0,0,0.4);
  border: 2px solid #3a3d4e;
}
h1 {
  font-size: 1.5rem;
  text-align: center;
  margin-bottom: 20px;
  color: var(--accent);
  letter-spacing: 1px;
}
.display {
  background: #0f111a;
  border-radius: 12px;
  padding: 16px;
  margin-bottom: 24px;
  display: flex;
  justify-content: space-around;
  align-items: center;
  border: 2px solid #3a3d4e;
}
.current-floor {
  font-size: 3rem;
  font-weight: 700;
  color: var(--accent);
  min-width: 2ch;
  text-align: center;
  line-height: 1;
}
.direction {
  font-size: 2rem;
  color: var(--muted);
  min-width: 2ch;
  text-align: center;
}
.doors {
  font-size: 1rem;
  color: var(--muted);
  text-transform: uppercase;
  letter-spacing: 1px;
}
.floor-buttons {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 12px;
  margin-bottom: 20px;
}
.floor-btn {
  background: #3a3d4e;
  color: var(--text);
  border: 2px solid #4a4d5e;
  border-radius: 12px;
  padding: 16px 0;
  font-size: 1.25rem;
  font-weight: 600;
  cursor: pointer;
  transition: background 0.15s, transform 0.1s, border-color 0.15s;
  font-family: inherit;
}
.floor-btn:hover {
  background: #4a4d5e;
  border-color: var(--accent);
}
.floor-btn:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
}
.floor-btn:active {
  transform: scale(0.96);
}
.floor-btn.queued {
  background: var(--pressed);
  border-color: var(--pressed);
  color: #1a1c2c;
}
.status {
  text-align: center;
  font-size: 1rem;
  color: var(--muted);
  min-height: 1.5em;
}
[hidden] { display: none !important; }
@media (max-width: 400px) {
  .elevator-card { padding: 16px; }
  .current-floor { font-size: 2.5rem; }
  .direction { font-size: 1.5rem; }
  .floor-btn { padding: 12px 0; font-size: 1.1rem; }
}

const floors = [1, 2, 3, 4, 5, 6];
const state = {
  currentFloor: 1,
  direction: 'idle',
  doorsOpen: false,
  queue: [],
  moving: false,
  doorTimer: null,
  moveTimer: null
};

const currentFloorEl = document.getElementById('current-floor');
const directionEl = document.getElementById('direction');
const doorsEl = document.getElementById('doors');
const statusEl = document.getElementById('status');
const buttons = document.querySelectorAll('.floor-btn');

function updateUI() {
  currentFloorEl.textContent = state.currentFloor;
  directionEl.textContent = state.direction === 'up' ? '▲' : state.direction === 'down' ? '▼' : '—';
  doorsEl.textContent = state.doorsOpen ? 'Open' : 'Closed';
  buttons.forEach(btn => {
    const f = Number(btn.dataset.floor);
    btn.classList.toggle('queued', state.queue.includes(f));
  });
  if (!state.moving && state.queue.length === 0) {
    statusEl.textContent = 'Press a floor button to queue.';
  } else if (state.moving) {
    statusEl.textContent = `Moving ${state.direction}...`;
  } else {
    statusEl.textContent = 'Doors open. Waiting...';
  }
}

function openDoors() {
  state.doorsOpen = true;
  updateUI();
  state.doorTimer = setTimeout(() => {
    state.doorsOpen = false;
    updateUI();
    state.doorTimer = null;
    if (state.queue.length > 0) {
      startMoving();
    }
  }, 2000);
}

function startMoving() {
  if (state.moving || state.queue.length === 0) return;
  const target = state.queue[0];
  if (state.currentFloor === target) {
    state.queue.shift();
    openDoors();
    return;
  }
  state.moving = true;
  state.direction = target > state.currentFloor ? 'up' : 'down';
  updateUI();
  state.moveTimer = setInterval(() => {
    if (state.currentFloor < target) {
      state.currentFloor++;
    } else if (state.currentFloor > target) {
      state.currentFloor--;
    }
    updateUI();
    if (state.currentFloor === target) {
      clearInterval(state.moveTimer);
      state.moveTimer = null;
      state.moving = false;
      state.direction = 'idle';
      state.queue.shift();
      openDoors();
    }
  }, 1000);
}

function queueFloor(floor) {
  if (state.doorTimer) {
    clearTimeout(state.doorTimer);
    state.doorTimer = null;
    state.doorsOpen = false;
  }
  if (state.currentFloor === floor && !state.moving) {
    openDoors();
    return;
  }
  if (!state.queue.includes(floor)) {
    state.queue.push(floor);
    state.queue.sort((a, b) => a - b);
  }
  updateUI();
  if (!state.moving && !state.doorsOpen) {
    startMoving();
  }
}

buttons.forEach(btn => {
  btn.addEventListener('click', () => {
    const floor = Number(btn.dataset.floor);
    queueFloor(floor);
  });
});

updateUI();
